export const flagshipLines: Line[] = [
  {"id":"L001","speaker":"jordan","text":"Okay, I think that's everyone. Lena, are you joining from the airport?","start":4,"end":10.1},
  {"id":"L002","speaker":"lena","text":"I'm at the gate, so if you hear boarding announcements, that's me. I'll stay on mute.","start":11.1,"end":18.6},
  {"id":"L003","speaker":"jordan","text":"Perfect. Thanks for making time, everyone.","start":19.1,"end":22.1},
  {"id":"L004","speaker":"tom","text":"Sorry, sorry, I'm here. Can you hear me? My laptop decided this was a good time to install updates.","start":22.7,"end":32.1},
  {"id":"L005","speaker":"jordan","text":"We can hear you, Tom. You're good, we haven't started.","start":33.1,"end":38.3},
  {"id":"L006","speaker":"tom","text":"Okay, great. I'm going to keep my camera off for a minute while this thing finishes restarting itself.","start":39.3,"end":47.4},
  {"id":"L007","speaker":"dev","text":"Tom, you're echoing a little bit, I think you've got the meeting open in two tabs.","start":48.3,"end":56.3},
  {"id":"L008","speaker":"tom","text":"Oh, you're right, I do. Hang on. Is that better?","start":56.9,"end":61.5},
  {"id":"L009","speaker":"dev","text":"Much better.","start":62.5,"end":63.4},
  {"id":"L010","speaker":"jordan","text":"So the goal for today is pretty narrow.","start":63.9,"end":67.8},
  {"id":"L011","speaker":"jordan","text":"We need to leave this room with a scope for Atlas 2.0 and a launch date we actually believe in.","start":68.1,"end":77.6},
  {"id":"L012","speaker":"jordan","text":"Not a wish list. A scope and a date.","start":77.9,"end":82.1},
  {"id":"L013","speaker":"maya","text":"And an owner for each piece, ideally.","start":82.7,"end":86.3},
  {"id":"L014","speaker":"jordan","text":"And owners, yes. Maya's going to hold me to that.","start":86.9,"end":91.8},
  {"id":"L015","speaker":"marcus","text":"Can we also talk about the enterprise blockers? Because I've got three deals that are basically parked.","start":92.9,"end":100.6},
  {"id":"L016","speaker":"jordan","text":"Yes, that's on the agenda, it's section two. I promise we'll get there.","start":101.6,"end":108.2},
  {"id":"L017","speaker":"jordan","text":"Quick context first, and I'll keep it short.","start":108.5,"end":112.1},
  {"id":"L018","speaker":"jordan","text":"Q3 closed at one point nine million in new ARR, which is about eight percent under plan.","start":112.4,"end":121},
  {"id":"L019","speaker":"jordan","text":"Net revenue retention came in at ninety-four percent.","start":121.3,"end":125.4},
  {"id":"L020","speaker":"jordan","text":"That's the number that worries me more than new ARR, honestly.","start":125.7,"end":131.2},
  {"id":"L021","speaker":"jordan","text":"Because new ARR we can usually fix with pipeline and a couple of good months, but when retention slips, it compounds, and it means the product isn't doing the job for people who already bought it.","start":131.5,"end":148.8},
  {"id":"L022","speaker":"aisha","text":"Same. Ninety-four is the lowest we've been in six quarters.","start":149.4,"end":153.8},
  {"id":"L023","speaker":"jordan","text":"Right. And gross logo churn was eleven accounts in the quarter.","start":154.3,"end":159.8},
  {"id":"L024","speaker":"dev","text":"Eleven out of how many?","start":160.6,"end":163.2},
  {"id":"L025","speaker":"jordan","text":"Out of about three hundred and forty active accounts.","start":163.6,"end":168.2},
  {"id":"L026","speaker":"dev","text":"Okay, so a bit over three percent a quarter.","start":169.1,"end":173.7},
  {"id":"L027","speaker":"jordan","text":"Yeah. Which annualizes to something we really don't want to say out loud.","start":174.6,"end":180.4},
  {"id":"L028","speaker":"marcus","text":"Twelve-ish percent.","start":181.4,"end":182.4},
  {"id":"L029","speaker":"jordan","text":"You said it out loud.","start":183.3,"end":185.8},
  {"id":"L030","speaker":"marcus","text":"Somebody had to.","start":186.6,"end":188.1},
  {"id":"L031","speaker":"jordan","text":"So the framing I want to propose is that Atlas 2.0 is first a retention release, and second a new-logo release.","start":188.8,"end":198.6},
  {"id":"L032","speaker":"jordan","text":"But I know not everyone agrees with that ordering, which is fine. That's what today is for.","start":198.9,"end":206.9},
  {"id":"L033","speaker":"marcus","text":"I mean, I don't disagree that retention matters.","start":207.8,"end":211.4},
  {"id":"L034","speaker":"marcus","text":"I disagree that we can't do both in the same release.","start":211.7,"end":217.1},
  {"id":"L035","speaker":"jordan","text":"Fair. Let's hold that thought. I want the data on the table first.","start":217.8,"end":223.9},
  {"id":"L036","speaker":"maya","text":"Can I add one thing to context before we jump in?","start":224.6,"end":230.2},
  {"id":"L037","speaker":"jordan","text":"Go ahead.","start":230.9,"end":231.9},
  {"id":"L038","speaker":"maya","text":"Engineering capacity for Q1 is lower than people think.","start":232.8,"end":237.1},
  {"id":"L039","speaker":"maya","text":"We have two people on parental leave starting in January, and the platform migration eats roughly a third of the sync team.","start":237.4,"end":247.9},
  {"id":"L040","speaker":"maya","text":"So whatever we pick, it has to fit in about fourteen engineer-months, not twenty.","start":248.2,"end":255.3},
  {"id":"L041","speaker":"tom","text":"Fourteen including the security work, or on top of it?","start":255.8,"end":260.4},
  {"id":"L042","speaker":"maya","text":"Including. That's the whole pie.","start":261.3,"end":263.6},
  {"id":"L043","speaker":"tom","text":"Okay. That's going to matter later.","start":264.3,"end":267.2},
  {"id":"L044","speaker":"jordan","text":"Noted. Sofia, anything from design before we start?","start":268,"end":272.1},
  {"id":"L045","speaker":"sofia","text":"Just that we finished the offline research sessions last week, so I have real findings, not opinions.","start":272.9,"end":281.2},
  {"id":"L046","speaker":"sofia","text":"I'll share those when we get to the customer section.","start":281.5,"end":286.4},
  {"id":"L047","speaker":"jordan","text":"Great. And Lena, the launch side?","start":287,"end":290.1},
  {"id":"L048","speaker":"lena","text":"Mostly I need a date I can plan against. Events, the website, the analyst briefing, all of it hangs off that date.","start":291,"end":300.8},
  {"id":"L049","speaker":"lena","text":"If it slips after I've booked things, that's money we don't get back.","start":301.1,"end":307.6},
  {"id":"L050","speaker":"jordan","text":"Understood. Okay, agenda.","start":308.3,"end":309.7},
  {"id":"L051","speaker":"jordan","text":"One, customer signals. Aisha and Marcus.","start":310,"end":312.9},
  {"id":"L052","speaker":"jordan","text":"Two, engineering capacity and how we split it.","start":313.2,"end":316.8},
  {"id":"L053","speaker":"jordan","text":"Three, security and compliance with Tom.","start":317.2,"end":320},
  {"id":"L054","speaker":"jordan","text":"Four, design and the launch plan.","start":320.3,"end":323.2},
  {"id":"L055","speaker":"jordan","text":"And five, owners and open questions.","start":323.5,"end":326.4},
  {"id":"L056","speaker":"jordan","text":"I'm aiming to be done by the top of the hour.","start":326.7,"end":331.9},
  {"id":"L057","speaker":"dev","text":"Optimistic.","start":332.9,"end":333.8},
  {"id":"L058","speaker":"jordan","text":"I contain multitudes. Aisha, take it away.","start":334.8,"end":338.2},
  {"id":"L059","speaker":"aisha","text":"Thanks. So I went through every churned and downgraded account from the last two quarters.","start":341.6,"end":348.9},
  {"id":"L060","speaker":"aisha","text":"That's eleven churns this quarter and fourteen last quarter, plus nine downgrades.","start":349.2,"end":355.2},
  {"id":"L061","speaker":"aisha","text":"And I tagged the exit interviews and the support tickets leading up to each one.","start":355.5,"end":362.5},
  {"id":"L062","speaker":"aisha","text":"The number one reason, by a wide margin, is technicians losing their work when they don't have signal.","start":362.8,"end":371.5},
  {"id":"L063","speaker":"aisha","text":"Seventeen of the twenty-five churned accounts mentioned it in some form.","start":371.8,"end":377.4},
  {"id":"L064","speaker":"jordan","text":"Seventeen of twenty-five.","start":377.8,"end":379.4},
  {"id":"L065","speaker":"aisha","text":"Seventeen of twenty-five. Sometimes it's the first thing they say.","start":380.3,"end":384.9},
  {"id":"L066","speaker":"aisha","text":"The typical story is a technician is in a basement, or a rural site, or a hospital with thick walls, and they fill out a whole work order.","start":385.2,"end":398.5},
  {"id":"L067","speaker":"aisha","text":"Then they lose connection, the app spins, and when it comes back, the form is gone.","start":398.8,"end":407},
  {"id":"L068","speaker":"aisha","text":"Orchard Health told me one of their techs re-entered the same inspection three times in a day.","start":407.3,"end":414.9},
  {"id":"L069","speaker":"aisha","text":"And their ops manager, Greg, said something on our last check-in that stuck with me. He said, \"My guys have started writing things on paper first and typing them in later, which means I'm paying for software so they can do double data entry.\"","start":415.3,"end":435},
  {"id":"L070","speaker":"jordan","text":"Oof. That's a brutal quote.","start":435.7,"end":438.2},
  {"id":"L071","speaker":"aisha","text":"It is. And he wasn't even angry when he said it, he was just tired, which is honestly worse.","start":438.8,"end":447.9},
  {"id":"L072","speaker":"maya","text":"Is that the app crashing or the session timing out?","start":448.6,"end":453.7},
  {"id":"L073","speaker":"aisha","text":"Both, depending on the platform. On Android it's usually the session timeout.","start":454.1,"end":459.9},
  {"id":"L074","speaker":"aisha","text":"On iOS it's more that the form state isn't persisted when the app gets backgrounded.","start":460.2,"end":467.6},
  {"id":"L075","speaker":"dev","text":"That second one is a bug we can fix without any offline architecture, for what it's worth.","start":468.3,"end":476},
  {"id":"L076","speaker":"aisha","text":"Which would be great. But customers don't really separate those. To them it's just \"Lumen loses my work.\"","start":476.9,"end":486},
  {"id":"L077","speaker":"aisha","text":"Number two reason is pricing. Five accounts said we were too expensive for what they used.","start":486.3,"end":494.6},
  {"id":"L078","speaker":"aisha","text":"And when I dug into those five, four of them were only using scheduling. They never turned on the work order forms or the asset history, which is most of the value, so they were paying for a product they were using maybe a third of.","start":494.9,"end":515.7},
  {"id":"L079","speaker":"jordan","text":"So that's partly an onboarding problem, not just a price problem.","start":516.5,"end":522.1},
  {"id":"L080","speaker":"aisha","text":"I'd say mostly an onboarding problem. If they'd been using forms, I don't think price would have come up at all. But I don't want to over-claim, it's five accounts.","start":522.7,"end":536.8},
  {"id":"L081","speaker":"aisha","text":"And number three is a cluster I'd call \"we outgrew you.\" Bigger customers who wanted SSO, audit logs, that kind of thing.","start":537.2,"end":547.1},
  {"id":"L082","speaker":"marcus","text":"Which is exactly my point.","start":547.8,"end":550.1},
  {"id":"L083","speaker":"aisha","text":"It's part of your point. It was three accounts.","start":551.1,"end":555.5},
  {"id":"L084","speaker":"marcus","text":"Three accounts that were each bigger than ten of the small ones.","start":556.2,"end":562},
  {"id":"L085","speaker":"aisha","text":"That's true. I'm not disputing the dollar value.","start":562.6,"end":566.6},
  {"id":"L086","speaker":"jordan","text":"Can you give me the dollar split? Offline versus enterprise readiness?","start":567.1,"end":572.4},
  {"id":"L087","speaker":"aisha","text":"Roughly. Offline-related churn was about four hundred and ten thousand in ARR.","start":573.2,"end":579},
  {"id":"L088","speaker":"aisha","text":"The enterprise-readiness churn was about two hundred and sixty thousand.","start":579.4,"end":584.5},
  {"id":"L089","speaker":"jordan","text":"Okay. So offline is bigger in dollars too, not just in count.","start":585.2,"end":590.7},
  {"id":"L090","speaker":"aisha","text":"In churn, yes. Marcus is going to tell you about pipeline, which is a different picture.","start":591.3,"end":599.4},
  {"id":"L091","speaker":"marcus","text":"Yeah. So, can I go?","start":600.1,"end":602.7},
  {"id":"L092","speaker":"jordan","text":"Go.","start":603.6,"end":604.4},
  {"id":"L093","speaker":"marcus","text":"Okay. Pipeline-wise, I have three enterprise deals in late stage that are blocked on the same two things.","start":605.4,"end":614.1},
  {"id":"L094","speaker":"marcus","text":"Sock two Type Two and samel single sign-on.","start":614.4,"end":618.4},
  {"id":"L095","speaker":"marcus","text":"Brightline Logistics, Kessler Field Services, and Orchard's parent company, which is a separate deal from the Orchard account Aisha mentioned.","start":618.7,"end":628.9},
  {"id":"L096","speaker":"marcus","text":"Combined, that's about one point two million in first-year ACV.","start":629.3,"end":633.9},
  {"id":"L097","speaker":"dev","text":"One point two total, or each?","start":634.9,"end":637.8},
  {"id":"L098","speaker":"marcus","text":"Total. I wish each.","start":638.5,"end":640.4},
  {"id":"L099","speaker":"marcus","text":"Brightline is the biggest, about five hundred and forty thousand, and they're the furthest along. Rachel, their director of field ops, is basically our champion at this point, she's been pushing it internally for two months.","start":640.7,"end":657.5},
  {"id":"L100","speaker":"marcus","text":"Kessler is around four hundred thousand. They're running a paid pilot with us right now, so they've actually used the product, and the pilot's going well, but procurement won't sign the full contract without the report.","start":657.8,"end":675.3},
  {"id":"L101","speaker":"marcus","text":"And Orchard's parent company is about two hundred and seventy, and that one's earlier, honestly. I've had two calls with their IT folks and the first thing they sent was the security questionnaire, before they'd even seen a demo.","start":675.6,"end":693.6},
  {"id":"L102","speaker":"jordan","text":"And all three have the same competitor in the mix?","start":694.5,"end":699.3},
  {"id":"L103","speaker":"marcus","text":"Two of the three for sure. The third one, Kessler, I think they're evaluating one other vendor but they haven't told me who, and I haven't pushed.","start":700.2,"end":714.1},
  {"id":"L104","speaker":"maya","text":"What's the timeline on each? Like, when do they actually need to sign by?","start":715,"end":722},
  {"id":"L105","speaker":"marcus","text":"Brightline wants to sign this quarter if they can, but realistically Q1. Kessler's pilot wraps up in late November, and they told me end of Q2 is their absolute deadline to roll out, so they need to sign before that. Orchard parent, no real timeline yet.","start":723,"end":743.6},
  {"id":"L106","speaker":"marcus","text":"And every one of their security teams has sent the same questionnaire back with the same two red flags.","start":743.9,"end":752.6},
  {"id":"L107","speaker":"marcus","text":"No sock two report, no samel. They will not sign without at least a committed date.","start":752.9,"end":760.5},
  {"id":"L108","speaker":"maya","text":"A committed date, or the actual report?","start":761.5,"end":764.9},
  {"id":"L109","speaker":"marcus","text":"Brightline will sign with a committed date and a bridge letter. Kessler wants the report. Orchard's parent, I honestly don't know yet.","start":765.4,"end":776.4},
  {"id":"L110","speaker":"tom","text":"For what it's worth, a bridge letter only works if we've actually started the observation window.","start":777,"end":784.4},
  {"id":"L111","speaker":"tom","text":"You can't bridge to nothing.","start":784.7,"end":787.1},
  {"id":"L112","speaker":"marcus","text":"Right, so that's why I need us to start.","start":788.2,"end":792.3},
  {"id":"L113","speaker":"jordan","text":"Okay. Let's not solve it yet. Sofia, can you share the research?","start":793.3,"end":799},
  {"id":"L114","speaker":"sofia","text":"Sure, let me share my screen. Can everyone see a slide that says \"Offline field study\"?","start":799.7,"end":807.9},
  {"id":"L115","speaker":"dev","text":"Yep.","start":808.5,"end":809.4},
  {"id":"L116","speaker":"lena","text":"I see it. Barely, but I see it.","start":809.9,"end":813.8},
  {"id":"L117","speaker":"sofia","text":"So we did six sessions with technicians from four customers. Two HVAC, one medical equipment, one elevator maintenance.","start":814.7,"end":824},
  {"id":"L118","speaker":"sofia","text":"I'll skip the method stuff. Three findings.","start":824.3,"end":827.8},
  {"id":"L119","speaker":"sofia","text":"First, technicians don't think in terms of online and offline. They think in terms of \"will this save or not.\"","start":828.1,"end":837.5},
  {"id":"L120","speaker":"sofia","text":"Nobody asked for an offline mode toggle. Not one person.","start":837.8,"end":842.3},
  {"id":"L121","speaker":"sofia","text":"They want the app to just keep what they typed, and sync when it can.","start":842.6,"end":849.3},
  {"id":"L122","speaker":"sofia","text":"Second, the thing they need offline is narrow. It's the work order they're on, the asset history for that one site, and the form they're filling.","start":849.6,"end":861.9},
  {"id":"L123","speaker":"sofia","text":"They don't need the whole schedule, they don't need dispatch, they don't need reporting.","start":862.2,"end":868.7},
  {"id":"L124","speaker":"sofia","text":"One of the elevator technicians actually walked me through his day, and out of about nine hours, he said he's in a dead zone for maybe three, mostly in machine rooms and shafts, and that's exactly when he's filling out the inspection checklist, because he's standing in front of the equipment.","start":869,"end":892.4},
  {"id":"L125","speaker":"sofia","text":"So the moment he most needs the app is the moment it's least likely to work. Which is kind of the whole problem in one sentence.","start":892.7,"end":905.7},
  {"id":"L126","speaker":"dev","text":"That's actually really helpful. That shrinks the data we'd need to cache by a lot.","start":906.4,"end":913.5},
  {"id":"L127","speaker":"sofia","text":"That's what I hoped you'd say.","start":914.2,"end":917},
  {"id":"L128","speaker":"sofia","text":"Third, and this one surprised me, photo uploads are the biggest pain point.","start":917.4,"end":923.8},
  {"id":"L129","speaker":"sofia","text":"They take ten, fifteen photos per job and the upload fails silently on bad connections.","start":924.1,"end":931.1},
  {"id":"L130","speaker":"sofia","text":"Then the office calls them later asking where the photos are, and the tech has already driven to the next site.","start":931.4,"end":940.9},
  {"id":"L131","speaker":"aisha","text":"Oh, that's half my support tickets. The photo thing.","start":941.9,"end":946.5},
  {"id":"L132","speaker":"sofia","text":"Right. So my recommendation is that the first version of offline is really \"never lose work, and queue uploads,\" not a full offline app.","start":947.2,"end":958.1},
  {"id":"L133","speaker":"jordan","text":"That's a really useful reframe.","start":959.1,"end":961.6},
  {"id":"L134","speaker":"maya","text":"It also changes the engineering estimate quite a bit, which I'll get to.","start":962.1,"end":968.2},
  {"id":"L135","speaker":"lena","text":"Sorry, quick question, does \"queue uploads\" include signatures? Customers sign on the tablet at the end of a job.","start":968.9,"end":978.5},
  {"id":"L136","speaker":"sofia","text":"Yes. Signatures and photos both, they go in the same queue.","start":979.2,"end":984.5},
  {"id":"L137","speaker":"lena","text":"Great, thanks. That's a marketing story on its own.","start":985.4,"end":989.6},
  {"id":"L138","speaker":"jordan","text":"Okay. Aisha, anything else before we move on?","start":990.6,"end":994.7},
  {"id":"L139","speaker":"aisha","text":"One more data point. When I asked the churned accounts what would have kept them, offline came up more than price.","start":995.3,"end":1005.1},
  {"id":"L140","speaker":"aisha","text":"Even the price-sensitive ones said \"if it didn't lose my work, I'd pay for it.\"","start":1005.4,"end":1012.5},
  {"id":"L141","speaker":"marcus","text":"Respectfully, people say a lot of things in exit interviews.","start":1013.4,"end":1018.2},
  {"id":"L142","speaker":"aisha","text":"They do. But it's also in the tickets before they churned, not just the interviews.","start":1019.1,"end":1026.3},
  {"id":"L143","speaker":"marcus","text":"Fair.","start":1026.8,"end":1027.8},
  {"id":"L144","speaker":"jordan","text":"Okay. That's a good setup for the hard part. Maya, capacity.","start":1028.3,"end":1033.8},
  {"id":"L145","speaker":"maya","text":"Okay. So I've got rough estimates for the four big candidates.","start":1037.3,"end":1042.5},
  {"id":"L146","speaker":"maya","text":"Full offline mode, the way we scoped it in the spring, is about nine engineer-months.","start":1042.8,"end":1049.5},
  {"id":"L147","speaker":"maya","text":"Sofia's narrower version, \"never lose work plus an upload queue,\" is closer to five.","start":1049.8,"end":1056.7},
  {"id":"L148","speaker":"maya","text":"SAML SSO is about two engineer-months if we use a library and don't build our own.","start":1057.1,"end":1064.6},
  {"id":"L149","speaker":"maya","text":"The sock two work, the engineering part, logging, access reviews, change management tooling, call it two to three.","start":1064.9,"end":1073.8},
  {"id":"L150","speaker":"maya","text":"And route optimization, which is the thing the old roadmap had as the headline, is six at minimum.","start":1074.1,"end":1082.5},
  {"id":"L151","speaker":"jordan","text":"So five plus two plus three is ten. Plus route optimization is sixteen.","start":1083,"end":1089.6},
  {"id":"L152","speaker":"maya","text":"Which doesn't fit in fourteen.","start":1090.2,"end":1092.5},
  {"id":"L153","speaker":"jordan","text":"Which doesn't fit in fourteen.","start":1093.3,"end":1095.6},
  {"id":"L154","speaker":"dev","text":"And that's before any slippage, and we always slip on sync work.","start":1096.4,"end":1101.8},
  {"id":"L155","speaker":"maya","text":"Dev's being honest. Sync work has slipped every single time.","start":1102.5,"end":1107.1},
  {"id":"L156","speaker":"dev","text":"Every single time. Including the time I said it wouldn't.","start":1108.1,"end":1112.8},
  {"id":"L157","speaker":"jordan","text":"Okay, so something has to come out. I think route optimization moves to Q2.","start":1113.8,"end":1121.1},
  {"id":"L158","speaker":"marcus","text":"Hang on, before we cut things. Why are we assuming offline goes first?","start":1122.1,"end":1127.9},
  {"id":"L159","speaker":"marcus","text":"Because from where I sit, SSO and sock two unblock one point two million right now, and offline is a retention bet.","start":1128.3,"end":1139},
  {"id":"L160","speaker":"maya","text":"It's not a bet, Aisha just showed seventeen of twenty-five churns—","start":1139.7,"end":1144.7},
  {"id":"L161","speaker":"marcus","text":"Churned accounts, which are gone. I'm talking about money that's sitting on the table—","start":1144.7,"end":1150.6},
  {"id":"L162","speaker":"maya","text":"And I'm talking about the three hundred accounts that haven't churned yet.","start":1150.6,"end":1156},
  {"id":"L163","speaker":"maya","text":"If we lose another eleven next quarter, that's more than your three deals combined over two years.","start":1156.3,"end":1164.4},
  {"id":"L164","speaker":"marcus","text":"That assumes offline actually fixes churn, which we don't know.","start":1165.4,"end":1169.9},
  {"id":"L165","speaker":"aisha","text":"We kind of do know. I mean, it's the most consistent signal we have.","start":1170.9,"end":1177.4},
  {"id":"L166","speaker":"marcus","text":"It's a signal. It's not proof.","start":1177.9,"end":1181},
  {"id":"L167","speaker":"maya","text":"Nothing's proof until we ship it, Marcus. That's true of SSO too.","start":1181.7,"end":1187.3},
  {"id":"L168","speaker":"marcus","text":"No, SSO is different. They literally put it in writing. \"We will sign when you have SSO.\"","start":1188.3,"end":1196.6},
  {"id":"L169","speaker":"dev","text":"Can I jump in with something technical? I think it changes this argument a bit.","start":1197.2,"end":1204.1},
  {"id":"L170","speaker":"jordan","text":"Please.","start":1205.1,"end":1206},
  {"id":"L171","speaker":"dev","text":"SSO and offline don't really compete for the same people.","start":1206.6,"end":1211.4},
  {"id":"L172","speaker":"dev","text":"SSO is mostly backend auth work. The offline work is mostly the mobile team and the sync engine.","start":1211.7,"end":1219.8},
  {"id":"L173","speaker":"dev","text":"The overlap is basically me, because I'm on both reviews, and Ben, who owns the session layer.","start":1220.1,"end":1227.8},
  {"id":"L174","speaker":"maya","text":"That's true for SSO. It's less true for the sock two work, because that touches everything.","start":1228.5,"end":1235.8},
  {"id":"L175","speaker":"dev","text":"Right, the audit logging touches every service.","start":1236.4,"end":1239.9},
  {"id":"L176","speaker":"tom","text":"And the access reviews touch every system anyone has access to, which is a lot of systems.","start":1240.3,"end":1248.5},
  {"id":"L177","speaker":"marcus","text":"Okay, so then can't we just do both? Offline and the enterprise stuff, and push route optimization like Jordan said?","start":1249.5,"end":1258.7},
  {"id":"L178","speaker":"maya","text":"Five plus two plus three is ten out of fourteen. On paper, yes.","start":1259.5,"end":1265.5},
  {"id":"L179","speaker":"maya","text":"But I've watched us plan to ninety percent of capacity before, and it doesn't end well.","start":1265.8,"end":1273.8},
  {"id":"L180","speaker":"jordan","text":"What's the buffer you'd want?","start":1274.4,"end":1276.7},
  {"id":"L181","speaker":"maya","text":"Twenty percent minimum on anything involving sync. So realistically we can commit eleven, eleven and a half.","start":1277.4,"end":1285.9},
  {"id":"L182","speaker":"jordan","text":"So ten fits inside eleven and a half. Barely.","start":1286.4,"end":1290.8},
  {"id":"L183","speaker":"maya","text":"Barely. With zero room for the Android rewrite, which nobody has mentioned yet.","start":1291.5,"end":1297.3},
  {"id":"L184","speaker":"jordan","text":"Okay, before we go into Android, I want to step back for a second, because I think we're arguing about two different things.","start":1297.8,"end":1309.3},
  {"id":"L185","speaker":"jordan","text":"Marcus, your argument is that enterprise readiness unblocks known money that's on the table now. Maya, your argument is that offline protects the base, which is bigger money over a longer time. Is that fair?","start":1309.6,"end":1325.6},
  {"id":"L186","speaker":"marcus","text":"That's fair.","start":1326.5,"end":1327.5},
  {"id":"L187","speaker":"maya","text":"That's fair, yes. And I'd add that I'm also arguing about predictability. SSO is predictable. Sync is not. I'd rather put the unpredictable thing first so it has the most time.","start":1328.2,"end":1342.8},
  {"id":"L188","speaker":"marcus","text":"See, I'd argue the opposite. Put the predictable thing first so you actually ship something.","start":1343.7,"end":1351},
  {"id":"L189","speaker":"dev","text":"You're both kind of right, which is annoying.","start":1351.8,"end":1355.8},
  {"id":"L190","speaker":"jordan","text":"Very annoying. Okay, let's keep going and come back to the order, I think the Android piece affects it.","start":1356.3,"end":1365.3},
  {"id":"L191","speaker":"dev","text":"Oh, right, the legacy Android app.","start":1366,"end":1368.8},
  {"id":"L192","speaker":"jordan","text":"Remind me where that landed?","start":1369.5,"end":1372.1},
  {"id":"L193","speaker":"dev","text":"The legacy Android app is on an old framework that's going end-of-life next year. Somebody has to migrate it.","start":1373,"end":1381.9},
  {"id":"L194","speaker":"dev","text":"And offline is way easier to build once, on the new stack, than to build twice.","start":1382.2,"end":1390.3},
  {"id":"L195","speaker":"maya","text":"Which is the honest reason I'm nervous. If we build offline on the legacy Android app, we'll throw half of it away.","start":1391.3,"end":1401.9},
  {"id":"L196","speaker":"marcus","text":"So then build it on iOS first?","start":1402.8,"end":1406},
  {"id":"L197","speaker":"dev","text":"Sixty percent of technicians are on Android. Mostly cheap rugged tablets.","start":1406.8,"end":1412},
  {"id":"L198","speaker":"marcus","text":"Okay, never mind.","start":1412.6,"end":1414.1},
  {"id":"L199","speaker":"sofia","text":"Could we do the \"never lose work\" part as a smaller piece first? Like the form persistence bug Dev mentioned?","start":1414.7,"end":1424.7},
  {"id":"L200","speaker":"dev","text":"Yeah, the persistence fix is maybe two weeks. It's not the queue, it's just saving drafts locally.","start":1425.3,"end":1433.1},
  {"id":"L201","speaker":"sofia","text":"Because that alone would address a chunk of the complaints Aisha read out.","start":1433.6,"end":1440.3},
  {"id":"L202","speaker":"aisha","text":"A big chunk. Probably a third of the tickets.","start":1441.2,"end":1445.4},
  {"id":"L203","speaker":"jordan","text":"So that's a quick win we can ship in Q4, not Q1.","start":1446.3,"end":1452.1},
  {"id":"L204","speaker":"maya","text":"If Dev has two weeks in Q4.","start":1453,"end":1456.6},
  {"id":"L205","speaker":"dev","text":"I can find two weeks in Q4. Maybe not the same two weeks Maya is thinking of.","start":1457.1,"end":1465.7},
  {"id":"L206","speaker":"maya","text":"Ha. Fine.","start":1466.3,"end":1467.4},
  {"id":"L207","speaker":"jordan","text":"Okay. Let me try to say back where I think we are, and then you can tell me I'm wrong.","start":1468.3,"end":1477.3},
  {"id":"L208","speaker":"jordan","text":"Route optimization moves to Q2. Nobody's fighting for it in Q1.","start":1477.6,"end":1482.6},
  {"id":"L209","speaker":"lena","text":"I mean, marketing was kind of fighting for it. It's the flashier story.","start":1483.5,"end":1490},
  {"id":"L210","speaker":"jordan","text":"Is it a hill you want to die on?","start":1490.5,"end":1495.1},
  {"id":"L211","speaker":"lena","text":"No. \"Never lose your work\" is honestly a better headline for this audience.","start":1496,"end":1502.3},
  {"id":"L212","speaker":"jordan","text":"Okay. So route optimization moves to Q2.","start":1503.1,"end":1506.6},
  {"id":"L213","speaker":"jordan","text":"Then offline, the narrow version, and SSO both go in Atlas 2.0.","start":1507,"end":1513.2},
  {"id":"L214","speaker":"marcus","text":"And sock two.","start":1513.7,"end":1515.2},
  {"id":"L215","speaker":"jordan","text":"And the engineering part of sock two, which Tom's going to tell us about.","start":1516,"end":1522.7},
  {"id":"L216","speaker":"marcus","text":"Okay, I can live with that. As long as SSO isn't the thing that gets cut when offline slips.","start":1523.4,"end":1533.1},
  {"id":"L217","speaker":"maya","text":"I can't promise that, honestly. If offline slips, something has to give.","start":1534.1,"end":1540.3},
  {"id":"L218","speaker":"marcus","text":"Then I want it written down that SSO doesn't give.","start":1541,"end":1545.7},
  {"id":"L219","speaker":"maya","text":"And I want it written down that if we hit the sync problems we always hit, we don't add scope to make up for it.","start":1546.1,"end":1558.1},
  {"id":"L220","speaker":"jordan","text":"Okay, okay. Both of those are reasonable. Let's park the tiebreak until we hear from Tom, because the audit timeline might decide it for us.","start":1558.7,"end":1570.7},
  {"id":"L221","speaker":"marcus","text":"Fine.","start":1571.4,"end":1572.2},
  {"id":"L222","speaker":"maya","text":"Fine.","start":1573.1,"end":1574},
  {"id":"L223","speaker":"dev","text":"Can I ask one technical question before we move on? It's about the sync engine.","start":1574.6,"end":1581.8},
  {"id":"L224","speaker":"jordan","text":"Quick one.","start":1582.7,"end":1583.7},
  {"id":"L225","speaker":"dev","text":"For the upload queue, are we okay with last-write-wins on conflicts, or do we need real merges?","start":1584.4,"end":1592.6},
  {"id":"L226","speaker":"dev","text":"Because real merges means see are DTs or something like them, and that is not a five-month project.","start":1593,"end":1602},
  {"id":"L227","speaker":"sofia","text":"From the research, conflicts are really rare. Two techs almost never edit the same work order at the same time.","start":1603,"end":1612.1},
  {"id":"L228","speaker":"dev","text":"That's what I hoped. So last-write-wins with a conflict log for the office to review?","start":1612.8,"end":1620.2},
  {"id":"L229","speaker":"sofia","text":"I think that'd be fine for version one.","start":1621,"end":1625},
  {"id":"L230","speaker":"maya","text":"I'd want to see that in a doc before we commit, but yes, that's the right direction.","start":1626,"end":1633.8},
  {"id":"L231","speaker":"dev","text":"I'll write it up. A short spike doc on the queue and the conflict rules, by end of next week.","start":1634.5,"end":1644.5},
  {"id":"L232","speaker":"jordan","text":"Thanks, Dev. That's Friday the twenty-third?","start":1645.1,"end":1647.9},
  {"id":"L233","speaker":"dev","text":"Friday the twenty-third.","start":1648.9,"end":1650.3},
  {"id":"L234","speaker":"aisha","text":"Can I ask something about the data side? Where does the queue live on the device? Because some customers wipe tablets every night.","start":1650.7,"end":1662.4},
  {"id":"L235","speaker":"dev","text":"Ooh. Every night? Which customers?","start":1663.4,"end":1665.9},
  {"id":"L236","speaker":"aisha","text":"At least two of the medical equipment ones. It's a compliance thing for them.","start":1666.5,"end":1672.8},
  {"id":"L237","speaker":"dev","text":"Then queued work would get wiped before it syncs. That's a real problem.","start":1673.3,"end":1680},
  {"id":"L238","speaker":"maya","text":"How many accounts are we talking?","start":1680.8,"end":1683.9},
  {"id":"L239","speaker":"aisha","text":"I'd have to check. I don't know offhand.","start":1684.8,"end":1688.5},
  {"id":"L240","speaker":"jordan","text":"Let's take that offline. No pun intended.","start":1689.3,"end":1692.9},
  {"id":"L241","speaker":"dev","text":"Pun absolutely intended.","start":1693.8,"end":1695.3},
  {"id":"L242","speaker":"jordan","text":"Seriously though, Aisha, if you can find out which accounts wipe devices and how often, that changes Dev's design, so it's worth chasing quickly.","start":1696.3,"end":1707.5},
  {"id":"L243","speaker":"aisha","text":"I'll ask the account managers. Some of them will know off the top of their head, some won't.","start":1708.5,"end":1717.7},
  {"id":"L244","speaker":"jordan","text":"Moving on. Actually wait, one more thing on capacity.","start":1718.3,"end":1722.7},
  {"id":"L245","speaker":"jordan","text":"Maya, does the post gress migration still have to happen in Q1? Because that's a third of the sync team.","start":1723,"end":1733},
  {"id":"L246","speaker":"maya","text":"It does. The current database version goes out of support in March. We don't really have a choice there.","start":1733.8,"end":1743.4},
  {"id":"L247","speaker":"dev","text":"We could do it in stages, but it doesn't save total time, it just spreads it out.","start":1743.8,"end":1751.7},
  {"id":"L248","speaker":"jordan","text":"Okay. So that's fixed. Fine.","start":1752.1,"end":1754.6},
  {"id":"L249","speaker":"marcus","text":"Can I make one more argument and then I'll drop it?","start":1755.2,"end":1760.3},
  {"id":"L250","speaker":"jordan","text":"One.","start":1761.2,"end":1762.1},
  {"id":"L251","speaker":"marcus","text":"If we commit to SSO for March and miss, I lose all three of those deals. Not one of them. All three.","start":1763.2,"end":1774},
  {"id":"L252","speaker":"marcus","text":"They're going to sign with the competitor that already has it. I know which competitor, and they have it.","start":1774.3,"end":1783},
  {"id":"L253","speaker":"maya","text":"I hear you. I'm not trying to cut SSO. I'm trying to not over-promise.","start":1783.6,"end":1790.5},
  {"id":"L254","speaker":"marcus","text":"Then let's sequence it so SSO lands first. Like, in February, ahead of offline.","start":1791.5,"end":1798.1},
  {"id":"L255","speaker":"dev","text":"That's actually not crazy. SSO is the more predictable piece.","start":1798.6,"end":1803.5},
  {"id":"L256","speaker":"maya","text":"Hmm.","start":1804.3,"end":1805.1},
  {"id":"L257","speaker":"maya","text":"If SSO lands in February, does that give Brightline enough to sign in Q1?","start":1805.4,"end":1812.5},
  {"id":"L258","speaker":"marcus","text":"With the sock two window started too? Yes. I'm pretty sure.","start":1813.4,"end":1818.5},
  {"id":"L259","speaker":"maya","text":"Okay. I'm open to that. Sequencing it first doesn't cost us capacity, it just changes the order.","start":1819,"end":1827.5},
  {"id":"L260","speaker":"jordan","text":"Good. That feels like progress. Let's hear from Tom.","start":1828.3,"end":1832.4},
  {"id":"L261","speaker":"tom","text":"Okay. So the short version is the sock two clock is the long pole, not the engineering.","start":1835.5,"end":1844.1},
  {"id":"L262","speaker":"tom","text":"Type Two requires an observation period. The minimum most auditors will accept is three months.","start":1844.4,"end":1852},
  {"id":"L263","speaker":"tom","text":"Then the auditor needs four to six weeks after that to write the report.","start":1852.3,"end":1859},
  {"id":"L264","speaker":"tom","text":"So if we want a report in hand by, say, end of April, the observation window has to start in early January.","start":1859.3,"end":1869.9},
  {"id":"L265","speaker":"tom","text":"If it starts in February, we're looking at a report in late May or June.","start":1870.2,"end":1877.1},
  {"id":"L266","speaker":"marcus","text":"Kessler won't wait until June. They told me end of Q2 is their absolute hard stop.","start":1877.7,"end":1885.8},
  {"id":"L267","speaker":"tom","text":"Then we need to start by January sixth. That's the first Wednesday after New Year's.","start":1886.5,"end":1893.7},
  {"id":"L268","speaker":"maya","text":"And what has to be true for the window to start?","start":1894.5,"end":1899.9},
  {"id":"L269","speaker":"tom","text":"The controls have to be in place and operating. Audit logging, access reviews, the change management process, the vendor list, the policies.","start":1900.5,"end":1911.2},
  {"id":"L270","speaker":"tom","text":"Policies I can do myself. Most of them are drafted already.","start":1911.5,"end":1916.6},
  {"id":"L271","speaker":"tom","text":"I've got the information security policy, acceptable use, incident response, business continuity, and vendor management drafted. What I don't have is the vendor inventory, which means somebody has to tell me every SaaS tool we use that touches customer data, and I promise you it's more than anyone thinks.","start":1916.9,"end":1939.7},
  {"id":"L272","speaker":"maya","text":"I can get you the engineering list. It's probably twenty-something tools.","start":1940.4,"end":1946.1},
  {"id":"L273","speaker":"marcus","text":"Sales has a few too. The call recording tool, the CRM, the e-signature thing.","start":1947.1,"end":1954.2},
  {"id":"L274","speaker":"tom","text":"Right, all of those count. I'll send a form around next week, please just fill it out honestly, even the free tools people signed up for with their work email.","start":1954.9,"end":1968.8},
  {"id":"L275","speaker":"tom","text":"The tooling is the engineering part. Audit logs especially.","start":1969.1,"end":1973.3},
  {"id":"L276","speaker":"dev","text":"Audit logs across all services by January sixth is tight. But it's doable if we start in November.","start":1974.3,"end":1983.2},
  {"id":"L277","speaker":"dev","text":"The tricky part isn't writing the logs, it's that we have about fourteen services and four of them were written before anyone here worked at the company. Nobody really knows what half the endpoints do.","start":1983.5,"end":2001.5},
  {"id":"L278","speaker":"tom","text":"Which, to be fair, is exactly the kind of thing the auditor will ask about.","start":2002.4,"end":2009.4},
  {"id":"L279","speaker":"dev","text":"Right. So what I'd propose is we put a shared logging library in front of everything, ship it service by service, and start with the ones that touch customer data, so the work order service, the photo store, and auth.","start":2010.3,"end":2028.2},
  {"id":"L280","speaker":"maya","text":"And the old reporting service? That one still has direct database access from like three places.","start":2029,"end":2036.9},
  {"id":"L281","speaker":"dev","text":"That one's going to hurt. I'd want Ben on it, he's the only one who's been in that code recently.","start":2037.9,"end":2047.1},
  {"id":"L282","speaker":"tom","text":"As long as the customer data paths are covered by January sixth, the rest can come during the observation window. I'd rather have a documented gap than a rushed implementation that logs the wrong things.","start":2047.9,"end":2064.3},
  {"id":"L283","speaker":"maya","text":"Okay. I'll budget the audit logging work for November and December then, and Ben moves to SSO in January.","start":2065.2,"end":2075},
  {"id":"L284","speaker":"tom","text":"It doesn't have to be perfect. It has to be operating, and we fix gaps during the window.","start":2075.5,"end":2084.3},
  {"id":"L285","speaker":"tom","text":"Auditors are fine with remediations as long as they're documented.","start":2084.6,"end":2089.6},
  {"id":"L286","speaker":"jordan","text":"Okay. And do we have an auditor?","start":2090.6,"end":2094},
  {"id":"L287","speaker":"tom","text":"We have two quotes. I haven't booked either. One of them can start in January, the other one is booked until March.","start":2094.6,"end":2104.8},
  {"id":"L288","speaker":"jordan","text":"So we book the January one.","start":2105.4,"end":2108.4},
  {"id":"L289","speaker":"tom","text":"That's my recommendation. I just need budget sign-off. It's about forty-two thousand for the Type Two.","start":2108.9,"end":2116.1},
  {"id":"L290","speaker":"jordan","text":"You have it. I'll get finance to approve it this week.","start":2117,"end":2122.4},
  {"id":"L291","speaker":"tom","text":"Great.","start":2123.2,"end":2124},
  {"id":"L292","speaker":"marcus","text":"Can I tell Brightline and Kessler January sixth, then?","start":2124.9,"end":2129.3},
  {"id":"L293","speaker":"tom","text":"Not until the auditor's booked. Give me until end of month.","start":2130.3,"end":2136},
  {"id":"L294","speaker":"marcus","text":"End of October?","start":2136.6,"end":2138.1},
  {"id":"L295","speaker":"tom","text":"End of October. I'll have the engagement letter signed by the thirtieth.","start":2139,"end":2144.8},
  {"id":"L296","speaker":"marcus","text":"Okay. Then I'll hold the emails until you confirm.","start":2145.3,"end":2149.5},
  {"id":"L297","speaker":"tom","text":"Actually, no, you can send them now with \"targeting.\" Just don't say \"committed\" until I confirm.","start":2150.5,"end":2158.4},
  {"id":"L298","speaker":"marcus","text":"Got it. Targeting.","start":2158.9,"end":2160.3},
  {"id":"L299","speaker":"maya","text":"Tom, what about SSO from your side? Any requirements I should know about?","start":2161,"end":2167.6},
  {"id":"L300","speaker":"tom","text":"Two. It has to support octa and Azure AD, because every one of these enterprise accounts uses one of the two.","start":2168.5,"end":2178.6},
  {"id":"L301","speaker":"tom","text":"And we need SCIM provisioning eventually, but not for version one. Version one is just login.","start":2178.9,"end":2187.1},
  {"id":"L302","speaker":"dev","text":"Octa and Azure both speak samel, so that's the same work. SCIM is a separate project.","start":2187.6,"end":2195.8},
  {"id":"L303","speaker":"tom","text":"Right, SCIM can be Q2. Nobody's blocked on it yet.","start":2196.9,"end":2201.9},
  {"id":"L304","speaker":"marcus","text":"Kessler asked about SCIM.","start":2202.6,"end":2204.5},
  {"id":"L305","speaker":"tom","text":"Did they say they'd block on it?","start":2205,"end":2208.6},
  {"id":"L306","speaker":"marcus","text":"No. They asked about it.","start":2209.6,"end":2212},
  {"id":"L307","speaker":"tom","text":"Then it's Q2.","start":2212.7,"end":2214.1},
  {"id":"L308","speaker":"marcus","text":"Fine, fine.","start":2215.2,"end":2216.2},
  {"id":"L309","speaker":"tom","text":"One more thing, and this is a question I don't have an answer to.","start":2217,"end":2223.5},
  {"id":"L310","speaker":"tom","text":"We have three customers in the EU, and one of them asked about data residency last month.","start":2223.8,"end":2232},
  {"id":"L311","speaker":"tom","text":"If we add an EU region at some point, does that change the scope of the audit? I genuinely don't know.","start":2232.3,"end":2242.7},
  {"id":"L312","speaker":"maya","text":"I don't know either. I'd assume yes, but I don't actually know.","start":2243.6,"end":2249.8},
  {"id":"L313","speaker":"jordan","text":"Can we ask the auditor when you book them?","start":2250.6,"end":2255},
  {"id":"L314","speaker":"tom","text":"Yeah, I'll add it to the list. But it might change the cost.","start":2255.6,"end":2262.1},
  {"id":"L315","speaker":"jordan","text":"Understood. Let's not let it block the January start.","start":2262.8,"end":2267.4},
  {"id":"L316","speaker":"tom","text":"Agreed. It shouldn't block anything for now.","start":2267.9,"end":2271.3},
  {"id":"L317","speaker":"jordan","text":"Okay. So I want to propose a decision here, because I think we have enough.","start":2271.8,"end":2278.5},
  {"id":"L318","speaker":"jordan","text":"Decision one. We start the sock two Type Two observation window on January sixth.","start":2278.8,"end":2286},
  {"id":"L319","speaker":"jordan","text":"Tom owns it. SAML SSO ships in Atlas 2.0 and lands first, in February, ahead of offline.","start":2286.3,"end":2295.1},
  {"id":"L320","speaker":"jordan","text":"Does anyone object?","start":2295.4,"end":2296.8},
  {"id":"L321","speaker":"maya","text":"No objection, as long as we keep the buffer.","start":2297.3,"end":2301.7},
  {"id":"L322","speaker":"marcus","text":"No objection. Obviously.","start":2302.3,"end":2303.8},
  {"id":"L323","speaker":"dev","text":"No objection. I'll need Ben for the SSO work, though.","start":2304.3,"end":2309.3},
  {"id":"L324","speaker":"maya","text":"You can have Ben in January. Not December.","start":2309.8,"end":2313.7},
  {"id":"L325","speaker":"dev","text":"January's fine.","start":2314.1,"end":2315.1},
  {"id":"L326","speaker":"jordan","text":"Okay. Decision one is made. Tom, Maya, thank you.","start":2315.8,"end":2319.8},
  {"id":"L327","speaker":"tom","text":"Thanks.","start":2320.6,"end":2321.4},
  {"id":"L328","speaker":"lena","text":"Can I ask, do we announce sock two at launch, or wait for the report?","start":2322.1,"end":2329.4},
  {"id":"L329","speaker":"tom","text":"Wait for the report. You don't want to announce an audit in progress.","start":2329.9,"end":2335.9},
  {"id":"L330","speaker":"tom","text":"You can say \"SOC 2 Type Two in progress\" on the trust page, but not in a press release.","start":2336.2,"end":2345.1},
  {"id":"L331","speaker":"lena","text":"Okay. That's helpful, I'll keep it off the launch messaging.","start":2345.6,"end":2350.3},
  {"id":"L332","speaker":"jordan","text":"Anything else on security before we go to launch?","start":2351.3,"end":2355.6},
  {"id":"L333","speaker":"tom","text":"Just the pen test. We're due for one, and enterprise customers will ask for the summary letter.","start":2356.2,"end":2364.8},
  {"id":"L334","speaker":"tom","text":"I'd like to do it in February, after SSO lands, so it covers the new auth.","start":2365.1,"end":2372.6},
  {"id":"L335","speaker":"maya","text":"That makes sense. Testing SSO before it exists is a waste of money.","start":2373.4,"end":2379.9},
  {"id":"L336","speaker":"tom","text":"Exactly.","start":2380.6,"end":2381.5},
  {"id":"L337","speaker":"jordan","text":"Okay, great. Thanks Tom.","start":2382.3,"end":2384.2},
  {"id":"L338","speaker":"jordan","text":"Okay, launch. Sofia, do you want to show the prototype first, or Lena the plan?","start":2387,"end":2394.3},
  {"id":"L339","speaker":"sofia","text":"Let me do the prototype. It's quick, and I think it informs the plan.","start":2394.9,"end":2401.7},
  {"id":"L340","speaker":"sofia","text":"Sharing again. Okay, so this is the work order screen on a tablet.","start":2402,"end":2408.3},
  {"id":"L341","speaker":"sofia","text":"The only new thing in the UI is this small status pill at the top. It says \"Saved on device,\" or \"Synced,\" or \"Waiting for signal.\"","start":2408.6,"end":2421},
  {"id":"L342","speaker":"sofia","text":"That's it. No offline mode switch, no separate screen.","start":2421.3,"end":2425.6},
  {"id":"L343","speaker":"aisha","text":"Oh, I love that. That's exactly what the techs asked for.","start":2426.3,"end":2431.7},
  {"id":"L344","speaker":"sofia","text":"And then if you tap the pill, you see the queue. \"Three photos waiting, one signature waiting.\"","start":2432.7,"end":2440.8},
  {"id":"L345","speaker":"sofia","text":"With a retry button, and the time it last tried.","start":2441.1,"end":2446.1},
  {"id":"L346","speaker":"dev","text":"How does the office side see it?","start":2446.9,"end":2450.2},
  {"id":"L347","speaker":"sofia","text":"On the dispatcher dashboard, the job shows a little cloud icon if it has unsynced work.","start":2450.7,"end":2458.7},
  {"id":"L348","speaker":"sofia","text":"So when the office calls asking where the photos are, they can already see \"it's queued on the tech's device.\"","start":2459,"end":2468},
  {"id":"L349","speaker":"aisha","text":"That will cut so many tickets. You have no idea.","start":2469,"end":2474.2},
  {"id":"L350","speaker":"marcus","text":"Honestly, that's a great demo. I'd use that in every sales call.","start":2474.8,"end":2480.6},
  {"id":"L351","speaker":"sofia","text":"That's the goal. It's subtle, but it changes the feeling of the product.","start":2481.2,"end":2487.3},
  {"id":"L352","speaker":"jordan","text":"What's the confidence level on this design? Is it tested?","start":2488.1,"end":2492.8},
  {"id":"L353","speaker":"sofia","text":"Paper-tested with four of the six technicians. Not tested on real devices yet.","start":2493.7,"end":2499.9},
  {"id":"L354","speaker":"sofia","text":"And paper testing is good for the concept, but it's terrible for anything involving timing, like how long you wait before you get nervous that your photo didn't upload, so I really don't want to lock the interaction details until we've seen it on a device with a flaky connection.","start":2500.2,"end":2525.1},
  {"id":"L355","speaker":"sofia","text":"I'd want to do a proper round with a working prototype before we lock it. Same six people if I can get them.","start":2525.5,"end":2537},
  {"id":"L356","speaker":"jordan","text":"When could you do that?","start":2538,"end":2540.5},
  {"id":"L357","speaker":"sofia","text":"If Dev's team can give me a clickable build by end of October, I can run it the first week of November.","start":2541.3,"end":2551.2},
  {"id":"L358","speaker":"dev","text":"A clickable build, not a real one, right? Fake data, no actual sync?","start":2552,"end":2558.5},
  {"id":"L359","speaker":"sofia","text":"Fake data is fine. I just need it on a tablet, with the network toggling.","start":2559.2,"end":2566.6},
  {"id":"L360","speaker":"dev","text":"Then yes, I can get you that.","start":2567.2,"end":2570.7},
  {"id":"L361","speaker":"sofia","text":"Then I'll run the device test with the six technicians and have results by November sixth.","start":2571.3,"end":2578.6},
  {"id":"L362","speaker":"jordan","text":"Great. Thank you.","start":2579.2,"end":2580.7},
  {"id":"L363","speaker":"maya","text":"One design question. What happens when the queue is full? Like if they're offline for a whole day?","start":2581.7,"end":2589.8},
  {"id":"L364","speaker":"sofia","text":"Good question. In the research, the longest anyone was offline was about five hours.","start":2590.4,"end":2596.7},
  {"id":"L365","speaker":"sofia","text":"But the rural HVAC folks said sometimes it's a full day.","start":2597,"end":2602},
  {"id":"L366","speaker":"dev","text":"Storage-wise, a full day of photos is maybe two or three hundred megabytes. Tablets can handle that.","start":2602.5,"end":2610.4},
  {"id":"L367","speaker":"maya","text":"And battery?","start":2611.3,"end":2612.2},
  {"id":"L368","speaker":"dev","text":"The queue shouldn't burn battery if we back off properly. I'll cover it in the spike doc.","start":2613.3,"end":2621.2},
  {"id":"L369","speaker":"maya","text":"Thanks.","start":2622.1,"end":2623},
  {"id":"L370","speaker":"jordan","text":"Okay, Lena. Launch plan.","start":2624,"end":2625.8},
  {"id":"L371","speaker":"lena","text":"Okay. I'll keep it tight because they're calling my group soon.","start":2626.5,"end":2632},
  {"id":"L372","speaker":"lena","text":"I want to propose we launch Atlas 2.0 at Field Service Connect, which is the biggest event for our buyers.","start":2632.3,"end":2641.5},
  {"id":"L373","speaker":"lena","text":"That's March twenty-fourth in Dallas. We have a booth, and I can get us a speaking slot if I confirm by mid-November.","start":2641.8,"end":2652.6},
  {"id":"L374","speaker":"marcus","text":"Every one of my top prospects goes to that.","start":2653.1,"end":2657.2},
  {"id":"L375","speaker":"lena","text":"Right. It's the one date where everyone's in one room.","start":2657.9,"end":2662.7},
  {"id":"L376","speaker":"lena","text":"And it's not just the booth. I'd want to brief the two analysts who cover field service software about two weeks before, so they're not hearing it on stage for the first time. They really don't like being surprised.","start":2663,"end":2682.4},
  {"id":"L377","speaker":"lena","text":"Then the website relaunch goes live the morning of the keynote, with the new pricing page if we have one, the trust page with the SOC 2 status, and the customer stories.","start":2682.7,"end":2698.9},
  {"id":"L378","speaker":"lena","text":"Which reminds me, I need two customer stories. Ideally one enterprise customer and one smaller customer who was going to churn and didn't.","start":2699.2,"end":2710.8},
  {"id":"L379","speaker":"aisha","text":"I can probably get you the second one from the beta. That's actually a great story if the beta goes well.","start":2711.4,"end":2720.9},
  {"id":"L380","speaker":"marcus","text":"And Brightline might do the first one if they sign in Q1. Rachel loves being on stage, honestly.","start":2721.4,"end":2730.2},
  {"id":"L381","speaker":"lena","text":"Okay, that would be amazing. I'll start the conversation with both of you after the brief is done.","start":2731.2,"end":2739.5},
  {"id":"L382","speaker":"maya","text":"March twenty-fourth for GA is aggressive for offline.","start":2740.1,"end":2744.1},
  {"id":"L383","speaker":"lena","text":"That's what I want to figure out. Is it aggressive, or impossible?","start":2744.9,"end":2751},
  {"id":"L384","speaker":"maya","text":"For SSO, it's comfortable. For the full upload queue, it's aggressive.","start":2751.7,"end":2756.9},
  {"id":"L385","speaker":"dev","text":"For the narrow version, on Android only, with last-write-wins, it's aggressive but doable.","start":2757.4,"end":2764.1},
  {"id":"L386","speaker":"dev","text":"On both platforms, it's not doable by March. iOS would be April at best.","start":2764.4,"end":2771.7},
  {"id":"L387","speaker":"lena","text":"So what if offline launches as a beta? On Android first?","start":2772.4,"end":2777.7},
  {"id":"L388","speaker":"jordan","text":"Say more.","start":2778.2,"end":2779.2},
  {"id":"L389","speaker":"lena","text":"We announce Atlas 2.0 GA on March twenty-fourth. SSO, audit logs, all the enterprise stuff is GA.","start":2780.1,"end":2787.7},
  {"id":"L390","speaker":"lena","text":"And \"Never lose work\" launches as a public beta, Android first, with iOS following.","start":2788.1,"end":2794.5},
  {"id":"L391","speaker":"lena","text":"Beta is honest, and it lets us show it on stage without promising it's perfect.","start":2794.8,"end":2801.8},
  {"id":"L392","speaker":"lena","text":"And frankly, every competitor demo at that show is going to be route optimization and AI scheduling, so if we show up with \"your technicians will never lose their work again,\" we're the only booth talking about the thing technicians actually complain about.","start":2802.2,"end":2822.9},
  {"id":"L393","speaker":"marcus","text":"I like that. I can sell enterprise readiness as GA and offline as the roadmap.","start":2823.7,"end":2831.3},
  {"id":"L394","speaker":"aisha","text":"And for my at-risk accounts, I can get them into the beta early. That's a retention play.","start":2831.9,"end":2840.2},
  {"id":"L395","speaker":"aisha","text":"I'd actually want to hand-pick the beta list. The accounts that churn on this issue.","start":2840.6,"end":2847.6},
  {"id":"L396","speaker":"aisha","text":"Not the ones that already churned, obviously, but the ones with the same pattern in their tickets. I have maybe twenty accounts in mind that are showing exactly the same signals the churned ones showed about two quarters before they left.","start":2847.9,"end":2867.6},
  {"id":"L397","speaker":"jordan","text":"That's smart. Maya, Dev, does beta on Android by March twenty-fourth work?","start":2868.3,"end":2874.1},
  {"id":"L398","speaker":"maya","text":"Beta on Android with the narrow scope? Yes. I'm comfortable with that.","start":2875.1,"end":2880.8},
  {"id":"L399","speaker":"dev","text":"Same. As long as \"beta\" means we can still change the conflict behavior.","start":2881.4,"end":2887.3},
  {"id":"L400","speaker":"lena","text":"It does. That's literally what beta means.","start":2888,"end":2891.6},
  {"id":"L401","speaker":"sofia","text":"And I'd want the status pill in the beta. It's not offline without it.","start":2892.3,"end":2898.6},
  {"id":"L402","speaker":"dev","text":"The pill's easy. The pill's the easy part.","start":2899.1,"end":2903.1},
  {"id":"L403","speaker":"jordan","text":"Okay. So I'm going to propose decision two.","start":2903.7,"end":2907.8},
  {"id":"L404","speaker":"jordan","text":"Atlas 2.0 goes GA on March twenty-fourth at Field Service Connect.","start":2908.1,"end":2913.6},
  {"id":"L405","speaker":"jordan","text":"SSO and the enterprise features are GA. \"Never lose work\" ships as a beta, Android first, with read access and queued writes.","start":2913.9,"end":2924.4},
  {"id":"L406","speaker":"jordan","text":"Route optimization moves to Q2.","start":2924.7,"end":2927.2},
  {"id":"L407","speaker":"jordan","text":"Objections?","start":2927.5,"end":2928.4},
  {"id":"L408","speaker":"marcus","text":"None.","start":2929,"end":2929.9},
  {"id":"L409","speaker":"maya","text":"None. Thank you for the buffer.","start":2930.6,"end":2933.4},
  {"id":"L410","speaker":"dev","text":"None.","start":2933.8,"end":2934.8},
  {"id":"L411","speaker":"sofia","text":"None from me.","start":2935.5,"end":2937},
  {"id":"L412","speaker":"aisha","text":"None. Very happy, actually.","start":2938,"end":2939.8},
  {"id":"L413","speaker":"tom","text":"Fine by me.","start":2940.8,"end":2942.2},
  {"id":"L414","speaker":"lena","text":"None. And I'll confirm the speaking slot.","start":2942.8,"end":2946.4},
  {"id":"L415","speaker":"jordan","text":"Great. Decision two is made.","start":2947.1,"end":2949.6},
  {"id":"L416","speaker":"lena","text":"Then I'll draft the launch brief and the beta criteria, and have it to everyone by November third.","start":2950,"end":2958.1},
  {"id":"L417","speaker":"jordan","text":"Perfect. Lena, before you go, pricing.","start":2959.1,"end":2962},
  {"id":"L418","speaker":"lena","text":"Ugh, pricing.","start":2963,"end":2964},
  {"id":"L419","speaker":"jordan","text":"Is \"Never lose work\" in the base plan, or is it an add-on?","start":2964.5,"end":2971.3},
  {"id":"L420","speaker":"lena","text":"I don't know. That's the honest answer.","start":2972,"end":2975.4},
  {"id":"L421","speaker":"marcus","text":"If it's an add-on, I'll have customers who feel like we're charging them to fix a bug.","start":2975.9,"end":2983.6},
  {"id":"L422","speaker":"aisha","text":"That's what I'm worried about too. The churned accounts would see it that way.","start":2984.1,"end":2990.6},
  {"id":"L423","speaker":"lena","text":"But if it's base, we leave money on the table with the enterprise accounts who'd pay for it.","start":2991.2,"end":2999.4},
  {"id":"L424","speaker":"jordan","text":"Could it be base for the core part, and an add-on for things like longer offline storage?","start":3000.2,"end":3008.1},
  {"id":"L425","speaker":"lena","text":"Maybe. I'd need to model it. I can't answer that today.","start":3008.6,"end":3013.6},
  {"id":"L426","speaker":"jordan","text":"Okay. Let's leave it open. It doesn't block the build either way.","start":3014,"end":3020.2},
  {"id":"L427","speaker":"lena","text":"Agreed. Okay, they're boarding my group. I'm going to drop.","start":3021.2,"end":3025.7},
  {"id":"L428","speaker":"jordan","text":"Safe travels, Lena. Thank you.","start":3026.2,"end":3028.6},
  {"id":"L429","speaker":"lena","text":"Bye everyone.","start":3029.2,"end":3030.1},
  {"id":"L430","speaker":"maya","text":"Before we wrap, I want to go back to the Android question.","start":3033.1,"end":3039},
  {"id":"L431","speaker":"maya","text":"Who owns the legacy Android migration? Because offline on Android depends on it, and right now nobody owns it.","start":3039.3,"end":3048.9},
  {"id":"L432","speaker":"dev","text":"I can't own it. I'm on the sync engine and SSO reviews.","start":3049.9,"end":3055.5},
  {"id":"L433","speaker":"maya","text":"I know. I'm not asking you.","start":3056.4,"end":3059.4},
  {"id":"L434","speaker":"maya","text":"But I want to be really clear that offline on Android is blocked on this. If nobody owns the migration by the first week of December, the March beta is at risk, and I'd rather say that now than in February.","start":3059.8,"end":3078.8},
  {"id":"L435","speaker":"jordan","text":"Is it a mobile team thing?","start":3079.4,"end":3082.4},
  {"id":"L436","speaker":"maya","text":"The mobile team is three people, and two of them are on the offline work.","start":3083.1,"end":3090.7},
  {"id":"L437","speaker":"jordan","text":"Hmm. So we need to hire, or borrow?","start":3091.3,"end":3095},
  {"id":"L438","speaker":"maya","text":"Or contract. But someone needs to decide, and I don't think it's going to be decided in this meeting.","start":3096,"end":3104.8},
  {"id":"L439","speaker":"jordan","text":"Okay. That's an open question too. Let's note it.","start":3105.6,"end":3109.8},
  {"id":"L440","speaker":"sofia","text":"Can I suggest the design side might help? We have a contractor who's done Android work.","start":3110.5,"end":3118.2},
  {"id":"L441","speaker":"maya","text":"For design, or engineering?","start":3118.6,"end":3120.7},
  {"id":"L442","speaker":"sofia","text":"Engineering. She's a front-end dev, but she's shipped Android apps before.","start":3121.3,"end":3126.8},
  {"id":"L443","speaker":"maya","text":"Send me her details. No promises.","start":3127.8,"end":3130.5},
  {"id":"L444","speaker":"sofia","text":"Will do.","start":3131.1,"end":3132.1},
  {"id":"L445","speaker":"maya","text":"And while we're on staffing, Jordan, I'll need you in the conversation with finance if we end up contracting. Last time it took six weeks to get a contractor approved, and we don't have six weeks.","start":3132.9,"end":3149.8},
  {"id":"L446","speaker":"jordan","text":"Agreed. Flag it to me as soon as you have a candidate and I'll walk it through.","start":3150.8,"end":3159.3},
  {"id":"L447","speaker":"aisha","text":"Sorry, can I go back to the beta list for a second?","start":3159.8,"end":3166},
  {"id":"L448","speaker":"jordan","text":"Sure.","start":3166.9,"end":3167.7},
  {"id":"L449","speaker":"aisha","text":"I'd like to propose a first cut by end of next week. Accounts with offline complaints in the last six months.","start":3168.7,"end":3178.2},
  {"id":"L450","speaker":"aisha","text":"I'll pull the churn interviews tagged \"offline\" too, so everyone can hear it in the customer's own words.","start":3178.5,"end":3187.4},
  {"id":"L451","speaker":"jordan","text":"That would be great. When can you share those?","start":3188.2,"end":3192.4},
  {"id":"L452","speaker":"aisha","text":"The interview clips I can share by Thursday, October twenty-second.","start":3193.4,"end":3198.4},
  {"id":"L453","speaker":"jordan","text":"Perfect.","start":3198.9,"end":3199.8},
  {"id":"L454","speaker":"marcus","text":"And send them to me too. I want to hear what Orchard said.","start":3200.5,"end":3206.6},
  {"id":"L455","speaker":"aisha","text":"I'll send them to everyone.","start":3207.7,"end":3210},
  {"id":"L456","speaker":"jordan","text":"Okay. We have about eight minutes. Let's go around for owners.","start":3212,"end":3217},
  {"id":"L457","speaker":"jordan","text":"And I'm going to ask everyone to say a date out loud, because I'm going to put it in the memo, and the recording will hold us to it.","start":3217.3,"end":3232},
  {"id":"L458","speaker":"dev","text":"That's mildly threatening.","start":3232.8,"end":3234.2},
  {"id":"L459","speaker":"jordan","text":"It's meant to be mildly threatening.","start":3234.7,"end":3237.5},
  {"id":"L460","speaker":"jordan","text":"Marcus, you're first, because I know you've been waiting.","start":3237.9,"end":3242.5},
  {"id":"L461","speaker":"marcus","text":"Ha. I'll email Brightline, Kessler, and the Orchard parent with the SSO and sock two timeline.","start":3243.5,"end":3251},
  {"id":"L462","speaker":"marcus","text":"Saying \"targeting,\" not \"committed,\" like Tom said.","start":3251.3,"end":3254.8},
  {"id":"L463","speaker":"marcus","text":"I'll get those out by Wednesday, October twenty-first.","start":3255.1,"end":3258.7},
  {"id":"L464","speaker":"tom","text":"And copy me, please, in case their security teams have follow-up questions.","start":3259.6,"end":3265.7},
  {"id":"L465","speaker":"marcus","text":"Will do.","start":3266.4,"end":3267.5},
  {"id":"L466","speaker":"jordan","text":"Tom?","start":3268.4,"end":3269.3},
  {"id":"L467","speaker":"tom","text":"Book the auditor and sign the engagement letter by October thirtieth. Confirm the January sixth start.","start":3269.8,"end":3277},
  {"id":"L468","speaker":"tom","text":"And I'll ask them about the EU residency question.","start":3277.3,"end":3281.9},
  {"id":"L469","speaker":"jordan","text":"Dev?","start":3282.7,"end":3283.5},
  {"id":"L470","speaker":"dev","text":"Spike doc on the upload queue and conflict rules, Friday the twenty-third. And the clickable build for Sofia by end of October.","start":3284.4,"end":3295},
  {"id":"L471","speaker":"jordan","text":"Sofia?","start":3295.7,"end":3296.6},
  {"id":"L472","speaker":"sofia","text":"Device test with the six technicians, results by November sixth. And send Maya the contractor's details.","start":3297.3,"end":3304.7},
  {"id":"L473","speaker":"jordan","text":"Aisha?","start":3305.2,"end":3306.1},
  {"id":"L474","speaker":"aisha","text":"Churn clips by the twenty-second, and the first cut of the beta list next week.","start":3306.9,"end":3313.9},
  {"id":"L475","speaker":"jordan","text":"Maya?","start":3314.7,"end":3315.5},
  {"id":"L476","speaker":"maya","text":"I'll rebalance the Q1 capacity plan with route optimization moved to Q2, and SSO sequenced first.","start":3316.5,"end":3324.1},
  {"id":"L477","speaker":"maya","text":"By Friday, October twenty-third.","start":3324.4,"end":3326.4},
  {"id":"L478","speaker":"jordan","text":"And Lena's doing the launch brief by November third.","start":3327.3,"end":3331.6},
  {"id":"L479","speaker":"jordan","text":"And I'll write up the decision memo with both decisions and circulate it today.","start":3331.9,"end":3338.2},
  {"id":"L480","speaker":"maya","text":"Today today?","start":3339.2,"end":3340.2},
  {"id":"L481","speaker":"jordan","text":"Today today. While it's fresh.","start":3340.8,"end":3343.3},
  {"id":"L482","speaker":"jordan","text":"Okay, open questions. Let me read them back so we don't lose them.","start":3343.6,"end":3349.7},
  {"id":"L483","speaker":"jordan","text":"One, does \"never lose work\" live in the base plan or as an add-on? Lena's going to model it.","start":3350,"end":3358.6},
  {"id":"L484","speaker":"jordan","text":"Two, who owns the legacy Android migration? Maya's going to come back on that.","start":3358.9,"end":3365.8},
  {"id":"L485","speaker":"jordan","text":"Three, does an EU region change the sock two scope? Tom's asking the auditor.","start":3366.1,"end":3372.7},
  {"id":"L486","speaker":"jordan","text":"And four, the tablet wipe thing Aisha raised. How many customers wipe devices nightly?","start":3373,"end":3380},
  {"id":"L487","speaker":"aisha","text":"I'll check on that one. I genuinely don't know how many.","start":3381.1,"end":3386.7},
  {"id":"L488","speaker":"dev","text":"That one worries me the most, honestly. If the queue gets wiped, we've built the opposite of \"never lose work.\"","start":3387.7,"end":3398},
  {"id":"L489","speaker":"maya","text":"Agreed. That one has to be answered before the spike doc is final.","start":3398.5,"end":3404.7},
  {"id":"L490","speaker":"dev","text":"I'll leave a placeholder in the doc for it.","start":3405.3,"end":3409.7},
  {"id":"L491","speaker":"jordan","text":"Anything I missed?","start":3410.7,"end":3412.1},
  {"id":"L492","speaker":"marcus","text":"The pen test. Tom said February.","start":3412.6,"end":3415.4},
  {"id":"L493","speaker":"tom","text":"Right. Pen test in February, after SSO lands.","start":3415.8,"end":3419.5},
  {"id":"L494","speaker":"jordan","text":"Got it, I'll add it to the memo.","start":3420.4,"end":3424.2},
  {"id":"L495","speaker":"sofia","text":"Can we also capture that there's no offline toggle in the UI? I don't want that to get re-litigated in two weeks.","start":3425,"end":3436.4},
  {"id":"L496","speaker":"jordan","text":"Good call. Design principle: no offline mode switch. The app just saves.","start":3437.4,"end":3443.3},
  {"id":"L497","speaker":"maya","text":"I'll back that up whenever it comes up.","start":3444.4,"end":3448},
  {"id":"L498","speaker":"jordan","text":"Okay. One last thing. I know the beginning of this got a little heated.","start":3448.8,"end":3455.4},
  {"id":"L499","speaker":"marcus","text":"Sorry about that.","start":3456.1,"end":3457.5},
  {"id":"L500","speaker":"maya","text":"Me too. For what it's worth, I think we landed in a good place.","start":3458.4,"end":3464.8},
  {"id":"L501","speaker":"marcus","text":"I think so too. SSO first, beta for offline, everybody gets something.","start":3465.7,"end":3471.5},
  {"id":"L502","speaker":"jordan","text":"Honestly, that was the right argument to have. I'd rather have it now than in February.","start":3472,"end":3479.8},
  {"id":"L503","speaker":"jordan","text":"The worst version of this meeting is the one where everyone nods, and then three weeks from now we find out sales and engineering had completely different launches in their heads.","start":3480.1,"end":3494.4},
  {"id":"L504","speaker":"aisha","text":"Agreed.","start":3495,"end":3495.8},
  {"id":"L505","speaker":"jordan","text":"Okay. Recap, really quickly.","start":3496.4,"end":3498.3},
  {"id":"L506","speaker":"jordan","text":"Sock two observation window starts January sixth. SSO lands in February, ahead of offline.","start":3498.6,"end":3505.4},
  {"id":"L507","speaker":"jordan","text":"Atlas 2.0 GA on March twenty-fourth at Field Service Connect, with \"never lose work\" in beta on Android.","start":3505.7,"end":3514.7},
  {"id":"L508","speaker":"jordan","text":"Route optimization moves to Q2.","start":3515.1,"end":3517.5},
  {"id":"L509","speaker":"jordan","text":"And the form persistence fix ships in Q4 as a quick win.","start":3517.9,"end":3523.7},
  {"id":"L510","speaker":"dev","text":"Two weeks. I said two weeks.","start":3524.3,"end":3527.2},
  {"id":"L511","speaker":"jordan","text":"You said two weeks. It's in the transcript now.","start":3528.3,"end":3532.6},
  {"id":"L512","speaker":"dev","text":"Great. Love that for me.","start":3533.1,"end":3535.6},
  {"id":"L513","speaker":"jordan","text":"Thanks, everyone. I'll send the memo this afternoon.","start":3536.4,"end":3540},
  {"id":"L514","speaker":"maya","text":"Thanks, Jordan.","start":3540.4,"end":3541.4},
  {"id":"L515","speaker":"tom","text":"Thanks all.","start":3542.1,"end":3543.1},
  {"id":"L516","speaker":"sofia","text":"Bye!","start":3543.9,"end":3544.8},
  {"id":"L517","speaker":"aisha","text":"Thanks, bye.","start":3545.4,"end":3546.3},
  {"id":"L518","speaker":"marcus","text":"Later.","start":3547.1,"end":3548},
];
